/**
 * TypeScript-enabled Function Node for Node-RED
 * Modified to support TypeScript compilation and userDir imports
 */

module.exports = function(RED) {
    "use strict";
    var util = require("util");
    var vm = require("vm");
    var path = require("path");
    var fs = require("fs-extra");
    
    // Import TypeScript compiler service
    var TypeScriptCompiler = require("../../../runtime/lib/typescript-compiler");
    
    function sendResults(node,send,_msgid,msgs,cloneFirstMessage) {
        if (msgs == null) {
            return;
        } else if (!util.isArray(msgs)) {
            msgs = [msgs];
        }
        var msgCount = 0;
        for (var m=0; m<msgs.length; m++) {
            if (msgs[m]) {
                if (!util.isArray(msgs[m])) {
                    msgs[m] = [msgs[m]];
                }
                for (var n=0; n < msgs[m].length; n++) {
                    var msg = msgs[m][n];
                    if (msg !== null && msg !== undefined) {
                        if (typeof msg === 'object' && !Buffer.isBuffer(msg) && !util.isArray(msg)) {
                            if (msgCount === 0 && cloneFirstMessage !== false) {
                                msgs[m][n] = RED.util.cloneMessage(msgs[m][n]);
                                msg = msgs[m][n];
                            }
                            msg._msgid = _msgid;
                        }
                        msgCount++;
                    }
                }
            }
        }
        if (msgCount>0) {
            send(msgs);
        }
    }

    function FunctionNode(n) {
        RED.nodes.createNode(this,n);
        var node = this;
        node.name = n.name;
        node.func = n.func;
        node.outputs = n.outputs;
        node.isTypeScript = n.isTypeScript || false;
        node.libs = n.libs || [];
        node.userDirImports = n.userDirImports || [];
        
        var handleNodeDoneCall = true;

        // Check if node is using TypeScript
        if (node.isTypeScript) {
            node.status({fill:"blue",shape:"ring",text:"TypeScript"});
        }

        var nodeContext = {
            id:node.id,
            name:node.name,
            outputCount:node.outputs,
            log: function() {
                node.log.apply(node, arguments);
            },
            error: function() {
                node.error.apply(node, arguments);
            },
            warn: function() {
                node.warn.apply(node, arguments);
            },
            debug: function() {
                node.debug.apply(node, arguments);
            },
            trace: function() {
                node.trace.apply(node, arguments);
            },
            send: function(msgs, cloneFirstMessage) {
                sendResults(node, node.send, node._msgid, msgs, cloneFirstMessage);
            },
            done: function() {
                if (handleNodeDoneCall) {
                    node.done.apply(node, arguments);
                }
            },
            status: function() {
                node.status.apply(node, arguments);
            },
            context: {
                set: function() {
                    node.context().set.apply(node,arguments);
                },
                get: function() {
                    return node.context().get.apply(node,arguments);
                },
                keys: function() {
                    return node.context().keys.apply(node,arguments);
                },
                get global() {
                    return node.context().global;
                },
                get flow() {
                    return node.context().flow;
                }
            },
            flow: {
                set: function() {
                    node.context().flow.set.apply(node,arguments);
                },
                get: function() {
                    return node.context().flow.get.apply(node,arguments);
                },
                keys: function() {
                    return node.context().flow.keys.apply(node,arguments);
                }
            },
            global: {
                set: function() {
                    node.context().global.set.apply(node,arguments);
                },
                get: function() {
                    return node.context().global.get.apply(node,arguments);
                },
                keys: function() {
                    return node.context().global.keys.apply(node,arguments);
                }
            },
            env: {
                get: function(envVar) {
                    return RED.util.getSetting(node, envVar);
                }
            },
            require: null,
            // Custom require for userDir imports
            requireUserDir: function(modulePath) {
                const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
                const fullPath = path.resolve(userDir, modulePath);
                try {
                    delete require.cache[require.resolve(fullPath)];
                    return require(fullPath);
                } catch (err) {
                    throw new Error(`Failed to require userDir module '${modulePath}': ${err.message}`);
                }
            }
        };

        var node_require = null;
        var nodeRequire = function(module) {
            if (!node_require) {
                node_require = require("module").createRequire(url.pathToFileURL(__filename));
            }
            return node_require(module);
        }
        nodeContext.require = nodeRequire;

        var functionText = n.func;
        var fullFunctionText = "";
        var functionGlobals = [];

        // Process TypeScript if enabled
        function processTypeScript(code, callback) {
            if (!node.isTypeScript) {
                console.log('[Function] Not TypeScript, skipping compilation');
                callback(null, code);
                return;
            }

            console.log('[Function] Processing TypeScript code...');
            console.log('[Function] Code length:', code.length);

            const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
            console.log('[Function] UserDir:', userDir);
            
            const compiler = new TypeScriptCompiler(userDir);
            
            // Configure TypeScript options
            const compilerOptions = {
                target: "ES2020",
                module: "commonjs",
                moduleResolution: "node",
                esModuleInterop: true,
                allowSyntheticDefaultImports: true,
                resolveJsonModule: true,
                baseUrl: userDir,
                paths: {
                    "@userDir/*": ["*"],
                    "@lib/*": ["lib/*"],
                    "@nodes/*": ["nodes/*"]
                }
            };

            console.log('[Function] Compiler options:', compilerOptions);

            compiler.compile(code, compilerOptions, (err, result) => {
                if (err) {
                    console.error('[Function] TypeScript compilation error:', err);
                    callback(err);
                    return;
                }
                
                console.log('[Function] TypeScript compilation result:', {
                    success: result.success,
                    errorCount: result.errors.length,
                    outputLength: result.outputText.length
                });
                
                if (result.errors && result.errors.length > 0) {
                    console.error('[Function] TypeScript errors:', result.errors);
                    const errorMessage = result.errors.map(e => e.message).join('\n');
                    callback(new Error(`TypeScript compilation errors:\n${errorMessage}`));
                    return;
                }
                
                console.log('[Function] TypeScript compilation successful');
                callback(null, result.outputText);
            });
        }

        var globalKeys = Object.keys(global);

        processTypeScript(functionText, function(err, processedCode) {
            if (err) {
                node.error(err.message);
                node.status({fill:"red",shape:"dot",text:"TypeScript error"});
                return;
            }

            try {
                var customRequire = function(moduleName) {
                    // Handle userDir imports
                    if (moduleName.startsWith('@userDir/')) {
                        const userDirPath = moduleName.replace('@userDir/', '');
                        return nodeContext.requireUserDir(userDirPath);
                    }
                    // Standard require
                    return nodeRequire(moduleName);
                };

                var functionHeader = `
                    var __node__ = {
                        id: nodeContext.id,
                        name: nodeContext.name,
                        outputCount: nodeContext.outputCount,
                        log: nodeContext.log,
                        error: nodeContext.error,
                        warn: nodeContext.warn,
                        debug: nodeContext.debug,
                        trace: nodeContext.trace,
                        send: nodeContext.send,
                        done: nodeContext.done,
                        status: nodeContext.status
                    };
                    var node = __node__;
                    var context = nodeContext.context;
                    var flow = nodeContext.flow;
                    var global = nodeContext.global;
                    var env = nodeContext.env;
                    var require = ${customRequire.toString()};
                    var requireUserDir = nodeContext.requireUserDir;
                    var RED = {
                        util: RED.util
                    };
                    ${RED._debug ? "var util = RED.util;" : ""}
                    var __send__ = function(msgs,cloneMsg) {
                        node.send(__msgid,msgs,cloneMsg);
                    };
                    var __done__ = function() {
                        node.done();
                    };
                `;

                var functionFooter = `
                    ;(async function(__msg__, __send__, __done__, __msgid__) {
                        var msg = __msg__;
                        var send = __send__;
                        var done = __done__;
                        ${processedCode}
                    })(__msg__, __send__, __done__, __msgid__);
                `;

                fullFunctionText = functionHeader + functionFooter;

                var scriptOpt = {
                    filename: 'Function node:'+node.name+' ['+ node.id+']',
                    displayErrors: true
                };

                var vmScript = new vm.Script(fullFunctionText, scriptOpt);
                var sandbox = {
                    nodeContext: nodeContext,
                    RED: RED,
                    __node__: {
                        id: node.id,
                        name: node.name,
                        outputCount: node.outputs,
                        log: function() {
                            node.log.apply(node, arguments);
                        },
                        error: function() {
                            node.error.apply(node, arguments);
                        },
                        warn: function() {
                            node.warn.apply(node, arguments);
                        },
                        debug: function() {
                            node.debug.apply(node, arguments);
                        },
                        trace: function() {
                            node.trace.apply(node, arguments);
                        },
                        send: function(id, msgs, cloneMsg) {
                            sendResults(node, node.send, id, msgs, cloneMsg);
                        },
                        done: function() {
                            if (handleNodeDoneCall) {
                                node.done.apply(node, arguments);
                            }
                        },
                        status: function() {
                            node.status.apply(node, arguments);
                        }
                    },
                    context: {
                        set: nodeContext.context.set,
                        get: nodeContext.context.get,
                        keys: nodeContext.context.keys,
                        get global() {
                            return nodeContext.context.global;
                        },
                        get flow() {
                            return nodeContext.context.flow;
                        }
                    },
                    flow: {
                        set: nodeContext.flow.set,
                        get: nodeContext.flow.get,
                        keys: nodeContext.flow.keys
                    },
                    global: {
                        set: nodeContext.global.set,
                        get: nodeContext.global.get,
                        keys: nodeContext.global.keys
                    },
                    env: {
                        get: nodeContext.env.get
                    },
                    require: customRequire,
                    requireUserDir: nodeContext.requireUserDir,
                    setTimeout: setTimeout,
                    clearTimeout: clearTimeout,
                    setInterval: setInterval,
                    clearInterval: clearInterval,
                    setImmediate: setImmediate,
                    clearImmediate: clearImmediate,
                    process: {
                        env: process.env,
                        version: process.version,
                        versions: process.versions,
                        platform: process.platform,
                        arch: process.arch
                    },
                    Buffer: Buffer,
                    Date: Date,
                    console: console,
                    util: util
                };

                if (util.hasOwnProperty('promisify')) {
                    sandbox.util.promisify = util.promisify;
                }

                const RESOLVING = 0;
                const RESOLVED = 1;
                const ERROR = 2;
                var state = RESOLVING;
                var messages = [];

                var processMessage = (() => {});

                node.on("input", function(msg,send,done) {
                    if(state === RESOLVING) {
                        messages.push({msg:msg, send:send, done:done});
                    } else if(state === RESOLVED) {
                        processMessage(msg, send, done);
                    }
                });

                // Wait for any async setup to complete
                const context = vm.createContext(sandbox);
                processMessage = function(msg, send, done) {
                    handleNodeDoneCall = true;
                    let functionText = `
                        (async function() {
                            ${processedCode}
                        })()
                    `;
                    
                    try {
                        var start = process.hrtime();
                        context.__msg__ = msg;
                        context.__msgid__ = msg._msgid;
                        context.__send__ = send;
                        context.__done__ = done;
                        
                        node.script.runInContext(context);
                        var duration = process.hrtime(start);
                        var converted = Math.floor((duration[0] * 1e9 + duration[1])/10000)/100;
                        node.metric("duration", msg, converted);
                        if (process.env.NODE_RED_FUNCTION_TIME) {
                            node.log("Function completed in "+converted+"ms");
                        }
                    } catch(err) {
                        done(err);
                    }
                };

                node.script = vmScript;
                state = RESOLVED;

                // Process any buffered messages
                messages.forEach(function(m) {
                    processMessage(m.msg, m.send, m.done);
                });
                messages = null;

                if (node.isTypeScript) {
                    node.status({fill:"green",shape:"dot",text:"TypeScript ready"});
                } else {
                    node.status({});
                }

            } catch(err) {
                state = ERROR;
                node.error(err);
                if (node.isTypeScript) {
                    node.status({fill:"red",shape:"ring",text:"TypeScript error"});
                } else {
                    node.status({fill:"red",shape:"ring",text:"function error"});
                }
            }
        });

        node.on("close", function() {
            node.status({});
        });
    }
    
    RED.nodes.registerType("function", FunctionNode);
    
    // Add TypeScript compilation endpoint
    RED.httpAdmin.post("/function/typescript/compile", function(req, res) {
        const code = req.body.code;
        const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
        const compiler = new TypeScriptCompiler(userDir);
        
        const compilerOptions = req.body.compilerOptions || {
            target: "ES2020",
            module: "commonjs",
            moduleResolution: "node",
            esModuleInterop: true,
            allowSyntheticDefaultImports: true,
            resolveJsonModule: true,
            baseUrl: userDir,
            paths: {
                "@userDir/*": ["*"],
                "@lib/*": ["lib/*"],
                "@nodes/*": ["nodes/*"]
            }
        };

        compiler.compile(code, compilerOptions, (err, result) => {
            if (err) {
                res.status(500).json({ error: err.message });
                return;
            }
            res.json(result);
        });
    });
    
    // Add TypeScript types endpoint
    RED.httpAdmin.get("/function/typescript/types", function(req, res) {
        const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
        const compiler = new TypeScriptCompiler(userDir);
        
        compiler.getAvailableTypes((err, types) => {
            if (err) {
                res.status(500).json({ error: err.message });
                return;
            }
            res.json(types);
        });
    });
     // Add endpoint to read userDir TypeScript files
     RED.httpAdmin.get("/function/typescript/userdir/*", function(req, res) {
        const requestedPath = req.params[0];
        const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
        const fullPath = path.resolve(userDir, requestedPath);
        
        // Security check - ensure we're not accessing files outside userDir
        if (!fullPath.startsWith(path.resolve(userDir))) {
            res.status(403).json({ error: "Access denied" });
            return;
        }
        
        // Check if file exists
        if (!fs.existsSync(fullPath)) {
            // Try with .ts extension
            const tsPath = fullPath + '.ts';
            if (fs.existsSync(tsPath)) {
                const content = fs.readFileSync(tsPath, 'utf8');
                res.type('text/plain').send(content);
            } else {
                res.status(404).json({ error: "File not found" });
            }
        } else {
            const content = fs.readFileSync(fullPath, 'utf8');
            res.type('text/plain').send(content);
        }
    });
    
    // Add endpoint to list TypeScript files in userDir
    RED.httpAdmin.get("/function/typescript/userdir-list", function(req, res) {
        const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
        const files = [];
        
        function scanDirectory(dir, prefix = '') {
            if (!fs.existsSync(dir)) return;
            
            try {
                const entries = fs.readdirSync(dir, { withFileTypes: true });
                
                for (const entry of entries) {
                    const fullPath = path.join(dir, entry.name);
                    const relativePath = prefix + entry.name;
                    
                    if (entry.isDirectory() && !entry.name.startsWith('.') && 
                        entry.name !== 'node_modules' && entry.name !== 'dist') {
                        scanDirectory(fullPath, relativePath + '/');
                    } else if (entry.isFile() && 
                              (entry.name.endsWith('.ts') || entry.name.endsWith('.d.ts'))) {
                        files.push({
                            path: relativePath,
                            fullPath: fullPath.replace(userDir, '').replace(/^\//, ''),
                            name: entry.name,
                            isTypeDef: entry.name.endsWith('.d.ts')
                        });
                    }
                }
            } catch (err) {
                console.error(`Error scanning directory ${dir}:`, err);
            }
        }
        
        scanDirectory(userDir);
        res.json({ files, userDir });
    });
    
    // Add schema validation endpoint for API endpoint node
    RED.httpAdmin.post('/function/typescript/validate-schema', function(req, res) {
        const { schemaFile, inputSchema, outputSchema } = req.body;
        
        try {
            const userDir = RED.settings.userDir || process.env.NODE_RED_HOME || '.';
            
            // Find the schema file
            const extensions = ['.js', '.ts', '.tsx'];
            let foundPath = null;
            const basePath = schemaFile.replace('@userDir/', '');
            
            for (const ext of extensions) {
                const testPath = path.resolve(userDir, basePath + ext);
                if (fs.existsSync(testPath)) {
                    foundPath = testPath;
                    break;
                }
            }
            
            if (!foundPath) {
                return res.json({
                    valid: false,
                    error: `Schema file not found: ${schemaFile}`
                });
            }
            
            // Read and parse the file to check exports
            const content = fs.readFileSync(foundPath, 'utf8');
            
            // Simple regex to find exports (could be more sophisticated)
            const exportRegex = /export\s+(?:const|let|var)\s+(\w+)/g;
            const exportDefaultRegex = /export\s+default\s+(\w+)/g;
            
            const exports = [];
            let match;
            
            while ((match = exportRegex.exec(content)) !== null) {
                exports.push(match[1]);
            }
            
            while ((match = exportDefaultRegex.exec(content)) !== null) {
                exports.push('default');
            }
            
            // Check if requested schemas exist
            const missingSchemas = [];
            if (inputSchema && !exports.includes(inputSchema)) {
                missingSchemas.push(inputSchema);
            }
            if (outputSchema && !exports.includes(outputSchema)) {
                missingSchemas.push(outputSchema);
            }
            
            if (missingSchemas.length > 0) {
                return res.json({
                    valid: false,
                    error: `Schema(s) not found: ${missingSchemas.join(', ')}. Available: ${exports.join(', ')}`
                });
            }
            
            // Try to get schema types (basic inference)
            const getSchemaType = (schemaName) => {
                const schemaRegex = new RegExp(`export\\s+(?:const|let|var)\\s+${schemaName}\\s*=\\s*z\\.([^\\(]+)`, 'g');
                const match = schemaRegex.exec(content);
                return match ? `z.${match[1]}` : 'unknown';
            };
            
            res.json({
                valid: true,
                inputSchemaType: inputSchema ? getSchemaType(inputSchema) : null,
                outputSchemaType: outputSchema ? getSchemaType(outputSchema) : null,
                availableExports: exports
            });
            
        } catch (error) {
            res.json({
                valid: false,
                error: `Validation error: ${error.message}`
            });
        }
    });
};